def selection_sort(arr):
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr
```

```python
def int_to_string(n):
  if n == 0:
    return "0"
  sign = "-" if n < 0 else ""
  n = abs(n)
  digits = []
  while n > 0:
    digits.append(str(n % 10))
    n //= 10
  return sign + "".join(digits[::-1])
```

